//! Model file format and hostile-length boundaries, independent of an advisor round trip.
use hft_sequencer::advisor::checkpoint::{self, FileError, Key};
use hft_types::{AccountId, StrategyId};

// Published file offsets + independently evaluated bitwise Castagnoli CRC (check vector
// "123456789" = e3069283). The golden is not generated by the encoder under test.
fn golden() -> Vec<u8> {
    const HEX: &str = "484654434b505431010002ff03000000341202ff020100000403020100000000140000000000000036c9fd1800000000000000000000000000000000000000000700000003000000aabbcc726177000100000000";
    (0..HEX.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&HEX[i..i + 2], 16).unwrap())
        .collect()
}

fn reseal(file: &mut [u8]) {
    file[40..44].fill(0);
    let crc = crc32c::crc32c(file);
    file[40..44].copy_from_slice(&crc.to_le_bytes());
}

#[test]
fn seq_399_checkpoint_file_matches_independent_golden() {
    let bytes = golden();
    assert_eq!(bytes.len(), 84);
    let file = checkpoint::decode(&bytes, 20).unwrap();
    assert_eq!(
        file.key,
        Key {
            kind_id: 0xff02,
            layout_version: 3,
            schema_id: 0xff021234,
            strategy: StrategyId(2),
            account: AccountId(1),
            last_seq: 0x01020304,
        }
    );
    assert_eq!(file.path_version, 7);
    assert_eq!(file.path, &[0xaa, 0xbb, 0xcc]);
    assert_eq!(file.samples, b"raw\0\x01\0\0\0\0");
    assert_eq!(file.body.as_ptr(), bytes[64..].as_ptr(), "borrow the source");
    let mut h = file.header(987_654_321);
    assert_eq!(h.last_ens, 987_654_321);
    assert_eq!(h.layout_version, 3);
    assert_eq!(h.len, 20);
    assert_eq!(checkpoint::encode(&h, file.body, 20).unwrap(), bytes);
    // Store begin metadata is not a second authority over lengths or checksums.
    h.len = u64::MAX;
    h.checksum = u64::MAX;
    h.last_ens = i64::MAX;
    assert_eq!(checkpoint::encode(&h, file.body, 20).unwrap(), bytes);
    h.path_version = 0;
    let empty = checkpoint::encode(&h, &[0; 8], 8).unwrap();
    let d = checkpoint::decode(&empty, 8).unwrap();
    assert_eq!(d.path_version, 0);
    assert!(d.path.is_empty() && d.samples.is_empty());
}

#[test]
fn seq_400_checkpoint_file_rejects_corruption_and_limits() {
    let bytes = golden();
    for n in 0..bytes.len() {
        assert!(checkpoint::decode(&bytes[..n], 20).is_err(), "cut at {n}");
    }
    let mut extra = bytes.clone();
    extra.push(0);
    assert_eq!(checkpoint::decode(&extra, 20).unwrap_err(), FileError::Length);
    for cap in [0, 19] {
        assert_eq!(checkpoint::decode(&bytes, cap).unwrap_err(), FileError::SizeLimit);
    }
    let mut cases = Vec::new();
    for (offset, error) in [
        (0, FileError::Magic),
        (8, FileError::Version),
        (22, FileError::Reserved),
        (23, FileError::Reserved),
        (44, FileError::Reserved),
        (63, FileError::Reserved),
    ] {
        let mut b = bytes.clone();
        b[offset] ^= 1;
        reseal(&mut b);
        cases.push((b, error));
    }
    for offset in [10, 12, 16, 20, 21, 24, 40, 64, 72, 83] {
        let mut b = bytes.clone();
        b[offset] ^= 1;
        cases.push((b, FileError::Checksum));
    }
    for len in [0u64, 19, 21, u64::MAX] {
        let mut b = bytes.clone();
        b[32..40].copy_from_slice(&len.to_le_bytes());
        reseal(&mut b);
        cases.push((
            b,
            if len > 20 {
                FileError::SizeLimit
            } else {
                FileError::Length
            },
        ));
    }
    for len in [13u32, 20, u32::MAX] {
        let mut b = bytes.clone();
        b[68..72].copy_from_slice(&len.to_le_bytes());
        reseal(&mut b);
        cases.push((b, FileError::Path));
    }
    let mut no_path_version = bytes.clone();
    no_path_version[64..68].fill(0);
    reseal(&mut no_path_version);
    cases.push((no_path_version, FileError::Path));
    for n in 0..8usize {
        let mut b = bytes[..64 + n].to_vec();
        b[32..40].copy_from_slice(&(n as u64).to_le_bytes());
        reseal(&mut b);
        cases.push((b, FileError::Path));
    }
    for (i, (file, expected)) in cases.into_iter().enumerate() {
        assert_eq!(checkpoint::decode(&file, 20).unwrap_err(), expected, "case {i}");
    }
    let d = checkpoint::decode(&bytes, 20).unwrap();
    let mut h = d.header(1);
    assert_eq!(
        checkpoint::encode(&h, d.body, 19).unwrap_err(),
        FileError::SizeLimit
    );
    h.path_version += 1;
    assert_eq!(checkpoint::encode(&h, d.body, 20).unwrap_err(), FileError::Path);
    assert_eq!(checkpoint::encode(&h, &[0; 7], 20).unwrap_err(), FileError::Path);
}
